export type PreviewAsset = { id: string; kind: "image" | "video"; url: string };

export function ResultPreview({ asset }: { asset: PreviewAsset | null }) {
  if (!asset) {
    return (
      <div className="preview-empty">
        <div className="preview-orbit" />
        <p>生成结果将在这里出现</p>
        <small>图片可直接预览，视频可在线播放</small>
      </div>
    );
  }
  return (
    <div className="result-preview">
      {asset.kind === "video" ? (
        <video src={asset.url} controls playsInline />
      ) : (
        // Signed asset URLs are generated by the authenticated backend.
        <img src={asset.url} alt="AI 生成结果" />
      )}
      <div className="result-actions">
        <a className="secondary-action" href={asset.url} download>下载素材</a>
      </div>
    </div>
  );
}
